.darma-loader-tw-dual-ring { position: relative; display: inline-block; width: var(--loader-size, 60px); height: var(--loader-size, 60px); }
.darma-loader-tw-dual-ring::before, .darma-loader-tw-dual-ring::after { content: ''; position: absolute; border-radius: 9999px; border: calc(var(--loader-size, 60px) * .07) solid transparent; }
.darma-loader-tw-dual-ring::before { inset: 0; border-top-color: var(--loader-color, #6366f1); border-bottom-color: var(--loader-color, #6366f1); animation: darma-loader-tw-dual-ring-twSpin var(--loader-speed, 1s) linear infinite; }
.darma-loader-tw-dual-ring::after { inset: 24%; border-left-color: var(--loader-secondary-color, #f43f5e); border-right-color: var(--loader-secondary-color, #f43f5e); animation: darma-loader-tw-dual-ring-twSpinBack calc(var(--loader-speed, 1s) * .8) linear infinite; }
@keyframes darma-loader-tw-dual-ring-twSpin { to { transform: rotate(360deg); } }
@keyframes darma-loader-tw-dual-ring-twSpinBack { to { transform: rotate(-360deg); } }

